            'name' => 'Người xây dựng',
            'light' => 'biết tổ chức, xây dựng việc có giá trị thực tế',
            'shadow' => 'dễ chịu áp lực hoặc làm quá sức',
        ],
    ],
    'attitude' => [
        1  => 'Mang khí chất tiên phong, thường chọn cách bước ra trước và tự mình mở đường khi đối diện những điều chưa quen thuộc.',
        2  => 'Sự mềm mại trong cảm xúc và khả năng cảm nhận người khác giúp tạo nên cảm giác gần gũi ngay từ những lần tiếp xúc đầu tiên.',
        3  => 'Năng lượng số 3 tích cực: nói chuyện và biểu đạt tự nhiên thường làm không khí quanh mình sống động hơn.',
        4  => 'Tiếp cận mọi việc bằng sự chắc chắn, ưu tiên tính ổn định và từng bước đi có nền tảng rõ ràng.',
        5  => 'Khả năng thích nghi nhanh cùng tinh thần yêu tự do thường tạo nên xu hướng dịch chuyển và đón nhận trải nghiệm mới.',
        6  => 'Sự gắn kết và sự quan tâm đến người thân thường được thể hiện rất sớm trong các mối quan hệ hoặc trách nhiệm mới.',
        7  => 'Thiên về quan sát và cảm nhận chiều sâu bên trong sự việc hơn là phản ứng ngay theo cảm xúc nhất thời.',
        8  => 'Tinh thần quyết đoán cùng khát vọng khẳng định giá trị cá nhân thường xuất hiện rất rõ trong cách hành động.',
        9  => 'Cách nhìn rộng và sự đồng cảm với người khác thường ảnh hưởng mạnh đến lựa chọn và phản ứng trong cuộc sống.',
        11 => 'Trực giác nhạy và khả năng cảm nhận dấu hiệu tinh tế thường tạo nên một trạng thái kết nối khá đặc biệt với thế giới xung quanh.',
        22 => 'Mang xu hướng xây dựng những giá trị có tính lâu dài, đồng thời luôn nhìn được hướng đi lớn phía sau từng lựa chọn.',
    ],
    'birthday' => [
        1  => 'Bản tính quyết đoán và độc lập tạo nên xu hướng tự mở đường trong những lựa chọn quan trọng.',
        2  => 'Sự tinh tế cùng khả năng thấu cảm khiến các kết nối trở nên mềm mại và dễ tạo tin cậy.',
        3  => 'Khả năng biểu đạt tự nhiên mang đến nguồn cảm hứng sáng tạo và vẻ lạc quan.',
        4  => 'Tư duy thực tiễn và tính kỷ luật là nền tảng cho những giá trị được xây dựng bền vững.',
        5  => 'Khát khao tự do và khả năng ứng biến linh hoạt giúp tinh thần luôn đổi mới trước biến động.',
        6  => 'Tinh thần trách nhiệm và lòng nhân ái gắn chặt với gia đình cùng các mối liên hệ cộng đồng.',
        7  => 'Trí tuệ sâu sắc nghiêng về quan sát và phân tích để chạm tới bản chất của sự việc.',
        8  => 'Biết chạy việc và quản trị giúp biến người–tiền–việc thành kết quả cụ thể.',
        9  => 'Lý tưởng sống cao đẹp thường hướng về giá trị nhân văn và tinh thần giúp ích rộng lớn.',
        10 => 'Nhịp khởi đầu mang theo xu hướng tự tái tạo và vượt khỏi những khuôn mẫu cũ.',
        11 => 'Số 11/2 mang trực giác nhạy bén, giúp nắm bắt những dấu hiệu tinh tế và lan tỏa cảm hứng.',
        12 => 'Sự kết hợp giữa tư duy sáng tạo và lòng nhiệt thành tạo nên cách thực thi ý tưởng rất có trách nhiệm.',
        13 => 'Thành quả đến từ sự kiên trì và kỷ luật, biến thử thách thành bậc thang tiến lên.',
        14 => 'Tự do và khuôn khổ luôn đan xen, mở ra cách sống cân bằng giữa trải nghiệm và cam kết.',
        15 => 'Sức hút tự nhiên và khả năng thuyết phục giúp tạo dựng vị thế cùng ảnh hưởng xã hội.',
        16 => 'Hành trình gắn với sự chuyển hóa nội tâm, hướng về thức tỉnh và những nhận ra mới.',
        17 => 'Tham vọng lớn hòa cùng chiều sâu trí tuệ tạo nên những thành tựu có giá trị nền tảng.',
        18 => 'Năng lực dẫn dắt nổi bật khi uy quyền cá nhân đi cùng tinh thần không vì lợi ích cá nhân.',
        19 => 'Bài học về tự lực giúp xây nền nội lực vững vàng trước khi trở thành điểm tựa cho người khác.',
        20 => 'Sự nhạy bén với bối cảnh và tài ngoại giao khéo léo giữ cho các kết nối luôn hài hòa.',
        21 => 'Khí chất tích cực cùng sự cởi mở thường thu hút niềm vui và sự ủng hộ từ tập thể.',
        22 => 'Số 22/4 thể hiện khả năng tổ chức lớn và đưa kế hoạch lớn vào thực tế.',
        23 => 'Khả năng thích nghi nhanh và tư duy sắc bén giúp làm chủ tình huống mới phát sinh.',
        24 => 'Tinh thần tận tụy tạo nên nền nếp ổn định và độ tin cậy trong nhiều khía cạnh đời sống.',
        25 => 'Sự kết hợp giữa logic và trực giác đem lại cái nhìn thấu suốt về thế giới xung quanh.',
        26 => 'Năng lực điều phối giúp dùng đúng người và việc để hướng tới mục tiêu chung một cách hiệu quả.',
        27 => 'Tri thức sâu rộng cùng tấm lòng nhân hậu tạo nên uy tín và chiều sâu nhân văn.',
        28 => 'Sức mạnh cá nhân khi đi cùng tinh thần hợp tác dễ tạo nên những bước tiến mạnh trong sự nghiệp.',
        29 => 'Số 29/11 tạo nên thế giới nội tâm phong phú, lý tưởng sống tinh tế và hành trình học cách cân bằng độ nhạy cảm cao.',
        30 => 'Ngôn ngữ và giao thiệp là nơi dấu ấn cá nhân hiện lên rõ ràng nhất.',
        31 => 'Tinh thần tự cường kết hợp tư duy tổ chức giúp bước đi vững vàng trên lộ trình thực tế.',
    ],
    'life_path' => [
        1  => 'Hành trình của sự độc lập và năng lực lãnh đạo. Bạn sinh ra để tự mở lối, học cách đứng trên đôi chân của mình và dẫn dắt người khác bằng sự tự tin và quyết đoán.',
        2  => 'Thiên về hòa hợp và kết nối, với trực giác khá nhạy trong các mối quan hệ. Sự dứt khoát cần được rèn thêm để tránh chần chừ.',
        3  => 'Đây là hành trình của sáng tạo và cảm hứng, nơi tiếng nói cá nhân dễ lan tỏa ra xung quanh. Việc giữ sự tập trung giúp ý tưởng đi vào đời thực.',
        4  => 'Con đường này xây trên kỷ luật và tính bền bỉ, tạo nền cho những giá trị lâu dài. Sự mềm dẻo sẽ giúp nhịp tiến lên không bị đóng khung.',
        5  => 'Gắn với chuyển động, trải nghiệm và những đổi thay liên tục. Một tâm thế vững sẽ giữ nhịp trước sự phân tán và chóng chán.',
        6  => 'Dấu ấn này thiên về chăm sóc, bảo bọc và giữ cho các mối liên hệ được êm. Ranh giới rõ ràng giúp tránh ôm đồm hoặc nắm quá chặt.',
        7  => 'Hành trình này đi sâu vào chiêm nghiệm và tri thức, nơi nội lực hình thành qua quan sát lặng lẽ. Xu hướng khép kín cần được dịu lại để sự sáng suốt mở ra trọn vẹn hơn.',
        8  => 'Hướng đến thành tựu cụ thể và khả năng điều phối người việc. Tham vọng chỉ thật sự bền khi đi cùng sự cân bằng và tiết chế.',
        9  => 'Đây là con đường của lòng nhân hậu và tầm nhìn rộng, thường hướng về những giá trị lớn hơn bản thân. Buông bớt kỳ vọng giúp tâm trí nhẹ và trong hơn.',
        11 => 'Trực giác nhạy bén và độ nhạy tinh tế tạo nên một kênh cảm nhận khá đặc biệt. Sự ổn định bên trong là điểm tựa để năng lượng 11 tỏa sáng.',
        22 => 'Mang khí chất người kiến tạo, hợp với những việc lớn và tầm nhìn dài. Sức ép trách nhiệm sẽ dịu khi nhịp làm việc đủ vững và đều.',
    ],
    'expression' => [
        1  => 'Sứ mệnh của bạn là trở thành người dẫn đầu, tự chủ và sáng tạo. Bạn được kỳ vọng sẽ để lại dấu ấn cá nhân mạnh mẽ và không ngại đi ngược đám đông.',
        2  => 'Phù hợp với việc kết nối và dung hòa, dùng sự tinh tế để giữ cho các mối quan hệ được cân bằng.',
        3  => 'Khả năng biểu đạt và sáng tạo là điểm sáng nổi bật, thường mang đến cảm hứng và sắc màu tích cực cho người xung quanh.',
        4  => 'Hành trình gắn với việc xây nền vững chắc, đưa ý tưởng vào thực tế bằng sự bền bỉ và ổn định.',
        5  => 'Tinh thần tự do và trải nghiệm mở ra xu hướng đổi mới, luôn tìm kiếm những góc nhìn khác biệt trước cuộc sống.',
        6  => 'Thiên về yêu thương và chăm sóc, thường giữ vai trò tạo nên cảm giác ấm áp và gắn kết.',
        7  => 'Con đường nghiêng về chiêm nghiệm và tìm kiếm chiều sâu tri thức, nơi sự sáng suốt hình thành qua quan sát nội tâm.',
        8  => 'Biết điều phối và nắm người–tiền–việc giúp chạm tới thành tựu và sự ổn định vật chất dễ hơn.',
        9  => 'Tinh thần nhân văn và lòng vị tha thường trở thành kim chỉ nam trong cách nhìn về con người và cuộc sống.',
        11 => 'Trực giác nhạy bén cùng khả năng cảm nhận tinh tế tạo nên vai trò truyền cảm hứng và đánh thức nhận thức.',
        22 => 'Năng lượng kiến tạo nổi bật: dễ biến ý tưởng lớn thành giá trị có ảnh hưởng lâu dài.',
    ],
    'soul' => [
        1  => 'Sâu thẳm bên trong, bạn khao khát quyền tự quyết, sự độc lập tuyệt đối và muốn khẳng định bản sắc cá nhân mà không bị ai can thiệp.',
        2  => 'Bình yên nội tâm đến khi có không gian của sẻ chia, thấu hiểu và hòa hợp.',
        3  => 'Động lực tinh thần mạnh nhất khi được tự do biểu đạt sáng tạo và lan tỏa niềm vui.',
        4  => 'Sự an tâm gắn với một lộ trình rõ ràng cùng những giá trị thực tiễn.',
        5  => 'Khao khát khám phá và nhu cầu tự do trải nghiệm giữ cho đời sống luôn có độ hứng khởi.',
        6  => 'Ý nghĩa cuộc sống hiện lên rõ nhất qua tình yêu thương và những mối liên hệ gắn kết sâu sắc.',
        7  => 'Nội tâm tĩnh lặng, cùng nhu cầu đi tìm bản chất sự thật, tạo nên trạng thái cân bằng trí tuệ.',
        8  => 'Tự hào khi có thành tựu hữu hình và biết chạy việc là nền của sự tự tin.',
        9  => 'Hạnh phúc sâu thẳm nảy nở khi được cống hiến cho những giá trị nhân văn và lý tưởng đẹp.',
        11 => 'Thế giới nội tâm nhạy bén và trực giác thôi thúc hành trình tìm đến chiều sâu tâm linh.',
        22 => 'Mong muốn xây dựng những điều lớn lao và đưa giấc mơ vào hiện thực là động lực nổi bật.',
    ],
    'personality' => [
        1  => 'Bạn toát ra phong thái tự tin, quyết liệt và độc lập. Người khác nhìn nhận bạn là một cá nhân mạnh mẽ, đôi khi hơi lấn hoặc khó tiếp cận.',
        2  => 'Vẻ ngoài ôn hòa cùng thái độ cầu thị tạo cảm giác ấm áp và dễ gần ngay từ lần đầu tiếp xúc.',
        3  => 'Phong thái tự tin cùng lối trò chuyện lôi cuốn thường làm nổi bật sự sáng tạo và khí chất tích cực.',
        4  => 'Sự chỉn chu, vững chãi và thực tế là những nét nổi bật tạo nên độ tin cậy cao.',
        5  => 'Sự tự do, năng động và khả năng thích ứng linh hoạt hiện lên khá rõ trước những thay đổi của bối cảnh xung quanh.',
        6  => 'Dấu ấn của sự tận tụy, ấm áp và ưu tiên hòa hợp thường để lại cảm giác dễ mến trong lòng người khác.',
        7  => 'Sự điềm tĩnh xen lẫn chút bí ẩn cùng tư duy sắc sảo tạo nên chiều sâu và sức hút trí tuệ riêng.',
        8  => 'Phong thái thành đạt, quyết đoán và bản lĩnh chạy việc thường hiện ra khá rõ.',
        9  => 'Hình ảnh gắn với lòng nhân ái, tầm nhìn bao quát và phong thái đĩnh đạc.',
        11 => 'Thần thái tinh tế cùng sự nhạy bén đặc biệt tạo nên một nét dẫn dắt giàu cảm hứng về mặt tinh thần.',
        22 => 'Diện mạo người lên kế hoạch chắc tay, tạo cảm giác tin cậy khi xây những giá trị lớn.',
    ],
    'maturity' => [
        1  => 'Giai đoạn trưởng thành đánh dấu sự tự chủ hoàn toàn. Bạn tìm thấy sức mạnh trong việc tự định đoạt cuộc sống và không còn dựa dẫm vào quan điểm của người khác.',
        2  => 'Ở Số Trưởng Thành 2, quá trình trưởng thành gắn với khả năng dung hòa, trong đó sự nhạy cảm được sử dụng một cách có ý thức.',
        3  => 'Với Số Trưởng Thành 3, trọng tâm nằm ở việc hoàn thiện biểu đạt, khi giao tiếp và sáng tạo trở nên rõ ràng và có chiều sâu hơn.',
        4  => 'Số Trưởng Thành 4 thể hiện xu hướng xây dựng nền tảng ổn định, nhấn vào kỷ luật và trật tự.',
        5  => 'Quá trình phát triển của Số Trưởng Thành 5 xoay quanh mở rộng trải nghiệm, đồng thời duy trì định hướng và kiểm soát.',
        6  => 'Số Trưởng Thành 6 gắn với trách nhiệm được gắn sâu hơn, riêng trong các mối quan hệ và vai trò chăm sóc.',
        7  => 'Ở Số Trưởng Thành 7, chiều hướng phát triển đi vào nội tâm, ưu tiên quan sát, chiêm nghiệm và tìm hiểu bản chất.',
        8  => 'Số Trưởng Thành 8 nghiêng về tổ chức và quản lý: dùng người–tiền–việc sao cho hiệu quả, có hệ thống.',
        9  => 'Số Trưởng Thành 9 cho thấy sự mở rộng nhận thức về giá trị chung, hướng đến đóng góp mang tính bao quát.',
        11 => 'Số Trưởng Thành 11 thể hiện sự phát triển của trực giác ở cấp độ cao, đi kèm khả năng kết nối và nhận thức tinh tế.',
        22 => 'Với Số Trưởng Thành 22/4, năng lực đặt trên nền tư duy tổ chức và thực tế.',
    ],
    'balance' => [
        1  => 'Bạn tìm lại trạng thái cân bằng bằng cách tự mình đối mặt với vấn đề thay vì trông chờ người khác. Hành động dứt khoát giúp bạn giải tỏa áp lực.',
        2  => 'Khả năng lắng nghe và thấu cảm giữ vai trò trọng tâm trong việc điều hòa cảm xúc. Sự kết nối và đồng hành với người xung quanh giúp nhịp sống dịu lại.',
        3  => 'Tư duy lạc quan và khả năng biểu đạt sáng tạo là cách giải tỏa áp lực khá tự nhiên. Chia sẻ ý tưởng hoặc tìm nguồn cảm hứng mới giúp tâm trí nhẹ hơn.',
        4  => 'Sự thực tế và tinh thần kỷ luật tạo nên nền tảng vững chắc. Bình tĩnh trở lại bằng cách sắp xếp lại trật tự và tập trung vào những điều có thể nắm giữ.',
        5  => 'Lòng hiếu kỳ và sự linh hoạt giúp vượt qua những bế tắc ngầm. Đổi góc nhìn hoặc bước vào một môi trường mới thường mang lại luồng sinh khí khác.',
        6  => 'Trách nhiệm và sự tận tâm với gia đình, cộng đồng là chỗ dựa giữ nội tại ổn định. Hòa khí trong quan hệ thân thiết đem lại cảm giác an tâm.',
        7  => 'Không gian riêng để chiêm nghiệm và phân tích sâu là điều cần thiết. Sự cân bằng đến qua việc học hỏi, quan sát và hiểu đúng bản chất vấn đề.',
        8  => 'Bản lĩnh chạy việc và kiểm soát thực tế giúp giữ vững tâm thế. Bám mục tiêu cụ thể và kết quả rõ giúp ổn định hơn.',
        9  => 'Cái nhìn bao dung và cách nhìn hướng thượng giúp xoa dịu những xung đột nội tâm. Sự vị tha và tinh thần giúp ích đem lại trạng thái nhẹ nhõm hơn.',
        11 => 'Trực giác nhạy bén kết hợp với sự điềm tĩnh là điểm tựa giữ vững trục tâm thức. Những cảm nhận tinh tế và nguồn cảm hứng tinh thần giúp lộ trình sáng hơn.',
        22 => 'Tư duy hệ thống và khả năng thực thi quy mô giúp kiểm soát tình hình. Việc xây dựng giá trị bền vững cho cộng đồng giữ cho nền tảng ổn định.',
    ],
    'rational_thought' => [
        1  => 'Cách tiếp cận vấn đề đề cao sự chủ động và khả năng tự quyết. Quyết định được đưa ra nhanh chóng, dứt khoát dựa trên logic bảo vệ lợi ích và vị thế cá nhân.',
        2  => 'Cách tiếp cận vấn đề thiên về thấu cảm và lắng nghe. Tư duy hướng đến hòa hợp, ưu tiên tìm điểm chung và giữ thế cân bằng giữa các bên.',
        3  => 'Trí tưởng tượng phong phú và lối nghĩ linh hoạt tạo nên nhiều hướng mở. Giải pháp thường đến từ sự sáng tạo bất ngờ, đi cùng cách truyền đạt cuốn hút và giàu cảm hứng.',
        4  => 'Nổi bật ở sự logic, thực tế và mạch nghĩ có trật tự. Mọi suy luận thường dựa trên chi tiết cụ thể, ưu tiên phương án an toàn và lộ trình rõ ràng.',
        5  => 'Tư duy nhạy và khả năng đổi hướng nhanh trước thay đổi. Cách xử lý vấn đề nghiêng về quan sát nhiều chiều, sẵn sàng làm mới để tìm phương án phù hợp nhất.',
        6  => 'Suy nghĩ đặt nặng trách nhiệm và sự ổn định. Các quyết định thường nghiêng về gia đình hoặc cộng đồng, đề cao sự chăm sóc và giữ nhịp hòa thuận.',
        7  => 'Lối nghĩ thiên về nghiên cứu và quan sát kỹ. Không vội kết luận, thường dành thời gian ngẫm lại và xem kỹ từng phần để chạm tới phần nền tảng của vấn đề.',
        8  => 'Tập trung mạnh vào hiệu quả thực tế và mục tiêu cụ thể. Nhìn xa hơn chút, dùng đúng người–tiền–việc để ra kết quả rõ và bền.',
        9  => 'Tầm nhìn rộng và lý tưởng nhân văn là điểm nổi bật. Suy nghĩ thường vượt khỏi chi tiết nhỏ để hướng về giá trị chung và điều có ích cho nhiều người.',
        11 => 'Sự nhạy cảm trong trực giác đi cùng độ sắc của nhận thức tinh thần. Có xu hướng nắm bắt lớp nghĩa ẩn và đưa ra những nhận định mang tính mở lối.',
        22 => 'Tư duy xây dựng trên quy mô lớn đi kèm khả năng triển khai mạnh. Có xu hướng hệ thống hóa ý tưởng phức tạp thành kế hoạch có tính ứng dụng cao.',
    ],
    'subconscious_self' => [
        1 => 'Nhu cầu tự chủ và khả năng dẫn dắt là hạt nhân trong tiềm thức. Khi quyền tự quyết bị hạn chế, dễ rơi vào trạng thái mất phương hướng hoặc cạn kiệt nhiệt huyết hành động.',
        2 => 'Sức mạnh tinh thần bắt nguồn từ sự gắn kết và khả năng thấu hiểu người khác. Việc thiếu vắng sự đồng điệu hoặc môi trường xung đột sẽ làm suy giảm nhiều động lực.',
        3 => 'Tự do biểu đạt và khả năng sáng tạo là phần sống động nhất của bản ngã. Khi ý tưởng không được nhìn nhận hoặc thiếu không gian để phát triển, cảm giác bí bách dễ tăng lên.',
        4 => 'Sự an tâm gắn liền với tính trật tự và khả năng kiên trì với mục tiêu đề ra. Môi trường thiếu quy hoạch hoặc các kế hoạch bị phá vỡ dễ cảm thấy bất an và mất đi sức bền.',
        5 => 'Khát khao đổi mới và trải nghiệm đa dạng là yếu tố thúc đẩy tâm lý quan trọng. Cảm giác bị gò bó trong những khuôn khổ quá cứng nhắc sẽ làm thui chột khả năng thích nghi và sự nhạy bén.',
        6 => 'Tâm thế sẵn sàng hỗ trợ và xây dựng môi trường hòa hợp là nền vững cho tâm thế. Nếu không thể hiện được vai trò chăm sóc hoặc gặp phải sự bất hòa, trạng thái tâm lý sẽ bị dao động.',
        7 => 'Xu hướng đào sâu chân lý và tích lũy tri thức là bản năng tiềm tàng. Việc bị ép buộc chấp nhận những thông tin hời hợt hoặc thiếu cơ sở logic khiến bản thân dễ nảy sinh tâm lý phản kháng.',
        8 => 'Động lực khẳng định giá trị cá nhân thông qua kết quả hữu hình là điểm tựa trong suy nghĩ. Khi những nỗ lực không mang lại thành quả thực tế, thường có cảm giác mất kiểm soát.',
        9 => 'Ý niệm phục vụ cộng đồng và lý tưởng bao dung là gốc rễ của mọi hành vi. Cảm giác thiếu đi ý nghĩa nhân văn trong công việc hay cuộc sống sẽ làm lu mờ đi nhiệt huyết tiềm ẩn.',
    ],
    'personal_year' => [
        1 => 'Khởi đầu chu kỳ mới với năng lượng tự chủ và quyết đoán. Đây là lúc đặt mục tiêu cá nhân, dám bước đi độc lập và gieo nền cho cả chu kỳ 9 năm.',
        2 => 'Năm nghiêng về kiên nhẫn và hợp tác. Cần lắng nghe, vun mối quan hệ và tìm điểm cân bằng trong nhiều mặt cuộc sống.',
        3 => 'Năm sáng tạo và biểu đạt bùng lên. Mở rộng quan hệ, chia sẻ ý tưởng và tìm cảm hứng mới làm cuộc sống sôi động hơn.',
        4 => 'Năm làm chắc nền và xếp lại trật tự. Bền bỉ, kỷ luật và chăm chi tiết thực tế giúp dựng chỗ đứng vững cho tương lai.',
        5 => 'Đánh dấu một năm của những biến động và sự tự do trải nghiệm. Khả năng thích nghi linh hoạt trước các cơ hội mới sẽ giúp phá vỡ những rào cản cũ, tạo ra những bước ngoặt bất ngờ nhưng đầy giá trị.',
        6 => 'Ưu tiên hàng đầu dành cho trách nhiệm với gia đình và các cam kết cộng đồng. Việc vun đắp tình cảm, thể hiện sự tận tâm và xây dựng môi trường sống hòa hợp sẽ mang lại sự an ổn nội tại.',
        7 => 'Năm của việc chiêm nghiệm sâu và trau dồi tri thức kỹ lưỡng. Đây là lúc cần tĩnh lặng để phân tích các bài học quá khứ, tập trung vào việc học tập kỹ lưỡng và phát triển sức mạnh tinh thần.',
        8 => 'Năm gặt hái nhờ biết chạy việc và nhìn xa. Quyết đoán khi quản lý người–tiền–việc và bám kết quả thực tế giúp khẳng định chỗ đứng và sự thịnh vượng.',
        9 => 'Khép lại chu kỳ cũ bằng sự bao dung và tinh thần giúp ích. Việc sàng lọc, buông bỏ những điều không còn phù hợp và hoàn tất các mục tiêu dang dở giúp chuẩn bị tâm thế sẵn sàng cho một khởi đầu mới.',
    ],
    'personal_month' => [
        1 => 'Tháng khởi đầu và hành động độc lập. Ưu tiên triển khai ý tưởng mới, tự quyết và hoàn thành mục tiêu cá nhân.',
        2 => 'Tháng kết nối và điều hòa. Ưu tiên lắng nghe, gây tin trong quan hệ và giải quyết việc bằng hợp tác, kiên nhẫn.',
        3 => 'Tháng sáng tạo và giao tiếp bùng lên. Việc chính: chia sẻ ý tưởng, mở rộng quan hệ và dùng cảm hứng làm mới việc hằng ngày.',
        4 => 'Tháng quy củ và bền bỉ. Cần rà soát chi tiết, xếp lại trật tự và làm việc có kỷ luật, trách nhiệm.',
        5 => 'Tháng thay đổi và thích nghi. Việc chính: phá rào cản cũ, dám thử hướng mới và tận dụng cơ hội bất ngờ để chuyển mình.',
        6 => 'Tháng nghiêng về gia đình và hòa hợp. Ưu tiên vun tình cảm, chăm người thân và giữ không gian sống–làm việc ấm, cân bằng.',
        7 => 'Tháng chiêm nghiệm và học hỏi sâu. Việc chính: học, nhìn bản chất sự việc và tĩnh lặng để đánh giá lại hướng đi.',
        8 => 'Tháng khẳng định bản lĩnh chạy việc và kết quả thực tế. Tập trung quản lý công việc, làm gọn để ra thành quả hữu hình.',
        9 => 'Tháng khép việc và bao dung. Việc chính: dứt điểm dự án còn dang dở, sàng lọc điều không còn phù hợp để sẵn sàng cho chặng sau.',
    ],
    'personal_day' => [
        1 => 'Ngày khởi sự và tự quyết. Ưu tiên nắm cơ hội mới, triển khai kế hoạch cá nhân và giữ tự chủ trong từng việc.',
        2 => 'Thời điểm của sự lắng nghe và hòa hợp. Ưu tiên các hoạt động hợp tác, hỗ trợ lẫn nhau và tìm kiếm sự đồng điệu trong các cuộc đối thoại hằng ngày.',
        3 => 'Ngày bùng nổ ý tưởng và sự cởi mở trong giao tiếp. Tập trung vào việc chia sẻ, bộc lộ năng lực sáng tạo và tạo dựng bầu không khí tích cực cho các mối quan hệ.',
        4 => 'Ngày nghiêng về ngăn nắp và làm thật. Ưu tiên dứt điểm việc tồn đọng bằng kỷ luật và tỉ mỉ từng chi tiết.',
        5 => 'Ngày của những trải nghiệm mới và sự linh hoạt thích nghi. Hãy sẵn sàng điều chỉnh lịch trình, đón nhận những bất ngờ và tìm kiếm những phương thức xử lý khác biệt.',
        6 => 'Hướng về các giá trị tình cảm và trách nhiệm với người thân. Việc chăm sóc gia đình và duy trì sự hòa thuận trong các tương tác là ưu tiên hàng đầu của ngày này.',
        7 => 'Thời gian dành cho việc nhìn nhận sâu và trau dồi tri thức. Hãy dành không gian riêng để chiêm nghiệm, học hỏi và đánh giá các vấn đề nền tảng một cách tỉnh táo.',
        8 => 'Ngày bám kết quả và thành quả hữu hình. Ưu tiên quản lý việc cho ra kết quả, quyết đoán ở quyết định thực tế để tạo uy tín.',
        9 => 'Ngày để hoàn tất, buông bỏ và hướng tới những giá trị bao dung. Việc khép lại các nhiệm vụ cũ, đạt được trạng thái an yên và sẵn sàng cho chu kỳ mới.',
    ],
    'period_cycle' => [
        1  => 'Chu kỳ này mở ra giai đoạn học cách tự chủ, xây dựng bản lĩnh cá nhân và dám bước ra khỏi sự phụ thuộc. Những khởi đầu mới cần được dẫn dắt bằng quyết đoán và ý thức rõ về bản sắc riêng.',
        2  => 'Chu kỳ này nhấn mạnh sự hợp tác, kiên nhẫn và khả năng cảm nhận người khác. Thành quả đến chậm nhưng bền khi biết lắng nghe, dung hòa và xây dựng lòng tin.',
        3  => 'Chu kỳ này thúc đẩy biểu đạt, giao tiếp và sáng tạo. Đây là thời gian mở rộng quan hệ, phát triển tiếng nói cá nhân và học cách dùng sự lạc quan một cách có định hướng.',
        4  => 'Chu kỳ này yêu cầu xây nền, làm việc có cấu trúc và kiên trì với các trách nhiệm thực tế. Sự ổn định đến từ kỷ luật, tổ chức và khả năng hoàn thiện từng bước nhỏ.',
        5  => 'Chu kỳ này mang lại thay đổi, dịch chuyển và nhu cầu mở rộng trải nghiệm. Bài học chính là quản lý tự do, thích nghi nhanh nhưng không đánh mất trọng tâm.',
        6  => 'Chu kỳ này hướng về gia đình, trách nhiệm, chăm sóc và các cam kết tình cảm. Sự trưởng thành đến từ việc yêu thương có ranh giới và tạo dựng môi trường hài hòa.',
        7  => 'Chu kỳ này thiên về học hỏi, nghiên cứu, chiêm nghiệm và phát triển chiều sâu nội tâm. Đây là giai đoạn cần không gian riêng để hiểu rõ bản chất của bản thân và cuộc sống.',
        8  => 'Chu kỳ này nghiêng về thành tựu, tài chính, quản lý người–tiền–việc và bản lĩnh chạy việc. Thành công bền cần bản lĩnh, đạo đức và dùng quyền lực đúng cách.',
        9  => 'Chu kỳ này mở rộng tầm nhìn nhân văn, thúc đẩy sự hoàn tất, buông bỏ và đóng góp cho giá trị lớn hơn bản thân. Bài học là lòng bao dung đi cùng sự tỉnh táo.',
        11 => 'Chu kỳ 11/2 làm nổi bật trực giác, cảm hứng và độ nhạy tinh thần. Nhịp này cần bám vào sự ổn định cảm xúc để tránh quá tải hoặc mơ hồ.',
        22 => 'Chu kỳ 22/4 nhấn mạnh khả năng kiến tạo quy mô lớn, tổ chức hệ thống và biến tầm nhìn thành giá trị thực tế. Áp lực cao cần được cân bằng bằng kế hoạch rõ và nhịp làm việc bền.',
    ],
    'hidden_passion' => [
        1 => 'Khát khao khẳng định bản sắc riêng và năng lực dẫn dắt là động lực nội tại rõ. Nguồn cảm hứng lớn khi được chủ động đưa ra quyết định và tiên phong trong các thử thách mới.',
        2 => 'Sự nhạy cảm tinh tế và mong muốn tạo dựng sự hòa hợp luôn hiện hữu trong tâm trí. Động lực bắt nguồn từ việc xây dựng các mối quan hệ tương hỗ và đóng góp vào sự gắn kết chung.',
        3 => 'Nhu cầu tự do biểu đạt cá tính và lan tỏa khí chất tích cực là hạt nhân của niềm đam mê. Có xu hướng tìm kiếm những phương thức sáng tạo để chia sẻ ý tưởng và gợi cảm hứng cho người xung quanh.',
        4 => 'Sự an tâm gắn liền với tính trật tự và các giá trị thực tiễn bền vững. Được thúc đẩy bởi việc thiết lập cấu trúc chặt chẽ, làm việc với dữ liệu logic và hoàn thiện mọi thứ một cách chuẩn xác.',
        5 => 'Khát vọng trải nghiệm sự đa dạng và mở rộng giới hạn cá nhân là động lực chủ đạo. Luôn cảm thấy hào hứng trước những thay đổi, sự đổi mới và những cơ hội khám phá điều mới mẻ.',
        6 => 'Tâm thế sẵn sàng gánh vác trách nhiệm và vun đắp các giá trị cộng đồng là điểm tựa tinh thần. Niềm hạnh phúc ẩn dấu, tạo ra môi trường ấm áp, an toàn và chăm sóc tốt cho những người thân thuộc.',
        7 => 'Sự tò mò trí tuệ và nhu cầu khám phá bản chất sự việc thúc đẩy tư duy không ngừng. Tìm thấy sự thỏa mãn khi được nghiên cứu kỹ lưỡng, chiêm nghiệm chân lý và tích lũy tri thức chuyên biệt.',
        8 => 'Hướng tới thành tựu hữu hình và khẳng định chỗ đứng. Động lực này thôi thúc làm ra kết quả, quản lý khéo người–tiền–việc và chinh phục mục tiêu tài chính, sự nghiệp.',
        9 => 'Lòng trắc ẩn và tầm nhìn hướng tới những giá trị nhân văn cao cả là kim chỉ nam cho hành động. Nhu cầu sâu sắc trong việc hỗ trợ cộng đồng, chia sẻ sự thấu hiểu và đóng góp cho sự phát triển chung.',
    ],
    'peak' => [
        1 => 'Giai đoạn độc lập và khẳng định bản lĩnh. Việc chính: rèn dẫn dắt, tự chủ quyết định và dám bước đi mang tính bước ngoặt.',
        2 => 'Thời kỳ đề cao sự hòa hợp và sức mạnh của sự kết nối tương hỗ. Thành công đến từ việc phát huy khả năng lắng nghe, thấu cảm và duy trì trạng thái cân bằng trong các mối quan hệ xã hội.',
        3 => 'Đỉnh cao của năng lực biểu đạt và tư duy sáng tạo không giới hạn. Đây là lúc cần tập trung bộc lộ tài năng thiên bẩm, lan tỏa ý tưởng và mở rộng tầm ảnh hưởng thông qua các giao tiếp tích cực.',
        4 => 'Chu kỳ nhấn mạnh vào tính thực tế, kỷ luật và nỗ lực bền bỉ. Việc thiết lập những nền tảng vững chãi và làm việc có hệ thống là chìa khóa để đạt được các thành tựu hữu hình và ổn định.',
        5 => 'Chuyển mình qua tự do cá nhân và thích ứng linh hoạt. Việc chính: nắm cơ hội thay đổi, phá giới hạn cũ để mở trải nghiệm và cách nhìn.',
        6 => 'Tập trung vào trách nhiệm với gia đình, cộng đồng và các giá trị nhân văn. Chu kỳ này hướng tới việc tạo dựng sự hài hòa, chăm sóc và giúp ích lợi ích chung của tập thể.',
        7 => 'Giai đoạn ưu tiên sự chiêm nghiệm nội tâm và tích lũy trí tuệ. Việc học tập, nghiên cứu và thấu hiểu bản chất sự việc, đạt được những nhận thức sắc sảo về cuộc sống và tinh thần.',
        8 => 'Đỉnh cao của thịnh vượng, quyền lực và quản trị thực tế. Việc chính: chạy việc hiệu quả, quyết đoán trong kinh doanh và khẳng định chỗ đứng bằng kết quả tốt.',
        9 => 'Chu kỳ của lòng bao dung và những cống hiến mang tính nhân đạo rộng lớn. Đây là thời điểm để lan tỏa các giá trị tích cực, hỗ trợ cộng đồng và hoàn thành các việc cần làm mang ý nghĩa tinh thần rộng.',
        11 => 'Thời điểm bừng sáng của trực giác và nhận thức tinh thần nhạy bén. Sức mạnh của giai đoạn này nằm ở khả năng gợi cảm hứng, định hướng và dẫn dắt người khác bằng một cách nhìn sâu và tinh tế.',
        22 => 'Khả năng đưa những kế hoạch lớn vào thực tế. Việc chính: biết tổ chức, làm bền bỉ và tạo giá trị dùng được lâu dài.',
    ],
    'karmic_debt' => [
        13 => '13/4 nhấn vào kỷ luật, trách nhiệm và khả năng xây nền từng bước. Dễ đi cùng cảm giác bị kéo vào việc lặp lại, quy trình hoặc những phần nền tảng không thể đốt cháy giai đoạn. Bài học của 13/4 là tạo cấu trúc ổn định và đi đường dài bằng năng lực thật.',
        14 => '14/5 đặt tự do vào bài kiểm tra về giới hạn, cam kết và khả năng tự điều chỉnh. Dễ nghiêng về phân tán, đổi hướng nhanh hoặc bị kéo bởi quá nhiều lựa chọn cùng lúc. Bài học của 14/5 là giữ sự linh hoạt mà không mất nhịp ổn định và phương hướng.',
        16 => '16/7 xoay quanh cái tôi, niềm tin và chiều sâu nội tâm. Dễ đưa người sở hữu vào các giai đoạn phải nhìn lại bản thân, điều chỉnh kỳ vọng hoặc buông bớt nhu cầu kiểm soát. Bài học của 16/7 là trưởng thành qua quan sát, chiêm nghiệm và thay đổi trong nhận thức.',
        19 => '19/1 nhấn vào tự chủ, bản lĩnh cá nhân và khả năng đứng vững khi ít điểm tựa. Dễ nghiêng về tự gánh, tự quyết hoặc khó nhận hỗ trợ. Bài học của 19/1 là giữ ý chí riêng mà không rơi vào cô lập, cứng đầu hoặc kiểm soát quá mức.',
    ],
    'karmic_debt_meta' => [
        'none' => 'Không có các số nợ nghiệp 13, 14, 16, 19',
    ],
    'karmic_lessons' => [
        1 => 'Vùng số 1 chưa vững: tính độc lập, sự quyết đoán và khả năng đứng vững với chính kiến thường phát triển chậm hơn các mặt khác.',
        2 => 'Vùng số 2 chưa vững: sự kiên nhẫn, khả năng lắng nghe và nhịp hợp tác trong quan hệ thường là vùng dễ thiếu ổn định.',
        3 => 'Vùng số 3 chưa vững: việc biểu đạt cảm xúc, giao tiếp cởi mở và cảm giác vui vẻ tự nhiên thường mất thời gian hơn mới hiện ra trọn vẹn.',
        4 => 'Vùng số 4 chưa vững: tính kỷ luật, sự đều đặn và khả năng hoàn thiện việc đến cùng thường cần nhiều thời gian để vững hơn.',
        5 => 'Vùng số 5 chưa vững: sự linh hoạt trước thay đổi, cảm giác thoải mái với trải nghiệm mới và tự do cá nhân thường không ổn định sớm.',
        6 => 'Vùng số 6 chưa vững: trách nhiệm trong gắn kết, sự chăm sóc và cam kết tình cảm sâu thường là vùng phát triển muộn hơn.',
        7 => 'Vùng số 7 chưa vững: chiều sâu nội tâm, năng lực phân tích và niềm tin vào trực giác thường chỉ chín dần sau nhiều trải nghiệm.',
        8 => 'Vùng số 8 chưa vững: khả năng quản lý vật chất, tiền bạc, quyền lực cá nhân và kết quả thực tế thường không phải điểm mạnh ngay từ đầu.',
        9 => 'Vùng số 9 chưa vững: lòng bao dung, tầm nhìn rộng và khả năng đặt mình vào bức tranh lớn thường phát triển qua trải nghiệm sống.',
    ],
    'karmic_lessons_meta' => [
        'none_short' => 'Không',
    ],
    'challenges' => [
        0 => 'Không có một chướng ngại nào bị ép buộc. Đây là giai đoạn bạn có quyền tự quyết định vượt qua sự trì trệ của bản thân. Thử thách nằm ở khả năng tự đưa ra định hướng và hành động bằng ý chí độc lập.',
        1 => 'Trận chiến với cái tôi. Phải học cách không để cái tôi trở nên độc đoán, áp đặt, đồng thời cũng không được để bản thân bị lu mờ hay phụ thuộc vào sự phán xét của người khác. Cần khẳng định bản thân một cách tích cực.',
        2 => 'Sự nhạy cảm quá mức. Dễ bị tổn thương bởi lời nói và thái độ của người khác, sinh ra tâm lý phòng thủ hoặc tự ái. Bài học là quản lý cảm xúc, không để sự tự ti cản trở các mối quan hệ hợp tác.',
        3 => 'Sự phân tán sức lực. Dễ bị cuốn vào nhiều thứ cùng lúc, lan man và thiếu sự tập trung. Cần rèn luyện kỷ luật ngôn từ, tránh phát ngôn thiếu suy nghĩ và tập trung hoàn thiện một mục tiêu cụ thể.',
        4 => 'Rào cản về kỷ luật và sự kiên trì. Cuộc sống ép buộc phải làm việc có tổ chức, thực tế và chăm chỉ. Việc lười biếng hoặc thiếu hệ thống sẽ lập tức mang lại những rắc rối cản bước tiến.',
        5 => 'Chấp nhận thay đổi và kiểm soát tự do. Dễ rơi vào trạng thái bốc đồng, muốn phá vỡ các nguyên tắc hoặc cả thèm chóng chán. Thử thách là giữ được sự linh hoạt nhưng không trốn tránh trách nhiệm.',
        6 => 'Bài học về sự cam kết và tiêu chuẩn cao. Dễ áp đặt sự hoàn hảo lên người khác hoặc can thiệp quá sâu vào đời tư của gia đình, bạn bè. Cần học cách buông bỏ sự kiểm soát và yêu thương không điều kiện.',
        7 => 'Sự cô lập và hoài nghi. Tâm trí có xu hướng phân tích quá mức, sinh ra đa nghi, lạnh lùng và khép kín. Bài học là sự tin tưởng, mở lòng chia sẻ và phát triển sức mạnh tinh thần thay vì tự nhốt mình trong suy lý.',
        8 => 'Sự ám ảnh về vật chất và quyền lực. Thử thách về các vấn đề tài chính, tham vọng và cái tôi cá nhân. Cần học cách quản lý tiền bạc một cách khôn ngoan, cân bằng giữa vật chất và đạo đức.',
    ],
    'pair_matrix' => [
        '1_1' => 'Sự lặp lại của số 1 nhấn mạnh tính độc lập và khả năng tự quyết, nhưng cần kiểm soát cái tôi để tránh rơi vào trạng thái độc đoán.',
        '1_2' => 'Khi số 1 đồng hành cùng số 2, cách dẫn dắt dịu hơn nhờ sự tinh tế: mục tiêu dễ đạt hơn nhờ hợp tác và thấu cảm.',
        '1_3' => 'Khi số 1 đi cùng số 3, ý tưởng dễ ra nhanh và dễ lôi cuốn người khác. Cái tôi mạnh cần được kiềm lại thì mới không lấn át người xung quanh.',
        '1_4' => 'Số 1 quyết đoán, số 4 thực tế: kế hoạch ít dừng ở ý tưởng, dễ làm ra bài bản và bền.',
        '1_5' => 'Số 1 với số 5 làm nhịp đổi nhanh. Giữ định hướng giúp không bị cuốn theo những thay đổi nhất thời.',
        '1_6' => 'Số 1 chủ động, số 6 mang trách nhiệm: dễ cân giữa khát vọng riêng và quan tâm tập thể.',
        '1_7' => 'Số 1 tự nghĩ, số 7 phân tích sâu: mỗi bước dễ có chiều sâu và cơ sở chắc hơn.',
        '1_8' => 'Khi số 1 đi cùng số 8, dễ bám hiệu quả thực tế, chạy việc và nắm người–tiền–việc chắc hơn.',
        '1_9' => 'Cặp số 1 và số 9 vừa có cá tính rõ vừa nghiêng về lý tưởng nhân văn, dễ hướng thành tựu sang việc có ích cho người khác.',
        '1_11' => 'Khi số 1 đi cùng số 11, cách dẫn dắt nghiêng về trực giác, dễ nắm nhanh các giá trị tinh thần cốt yếu.',
        '1_22' => 'Số 1 nhìn đường, số 22 xây được việc lớn: dễ mở dự án tầm cỡ và ảnh hưởng rộng.',
        '2_1' => 'Số 2 làm mềm quyết đoán số 1: khi cần dẫn dắt, phong thái vừa linh hoạt vừa ra việc.',
        '2_2' => 'Khi số 2 lặp lại, khả năng thấu cảm được đẩy mạnh. Giữ vững cảm xúc giúp các quyết định quan trọng không bị do dự quá lâu.',
        '2_3' => 'Số 2 mang sự thấu cảm, số 3 mang cách nói linh hoạt: ý tưởng dễ đến tai người khác nhẹ nhàng hơn, chạm đúng cảm xúc.',
        '2_4' => 'Sự hòa hợp của số 2 làm mềm đi tính kỷ luật của số 4, giúp các kế hoạch thực tế diễn ra nhịp nhàng và ổn định hơn.',
        '2_5' => 'Số 2 với số 5 dễ thích ứng: quan hệ vẫn giữ được ngay cả khi đời thay đổi nhiều.',
        '2_6' => 'Số 2 và số 6 nghiêng về dựng không gian yên bình: quan tâm và trách nhiệm bằng thái độ chân thành.',
        '2_7' => 'Số 2 lắng nghe, số 7 phân tích sâu: dễ nhìn nhiều phía trước khi kết luận.',
        '2_8' => 'Số 2 giúp số 8 chạy việc khéo hơn: ra mục tiêu thực tế mà vẫn giữ quan hệ tốt với cộng sự.',
        '2_9' => 'Số 2 bao dung, số 9 lý tưởng: dễ nghiêng sang hoạt động cộng đồng, nhân văn và vị tha.',
        '2_11' => 'Số 2 và số 11 rất nhạy tâm lý. Giữ nội tâm tĩnh giúp không bị quá tải cảm xúc từ bên ngoài.',
        '2_22' => 'Số 2 giúp số 22 kết nối người và mở hợp tác; các dự án lớn dễ đi xa hơn khi có ai biết dung hòa các bên.',
        '3_1' => 'Số 3 sáng tạo, số 1 tiên phong: ý tưởng mới dễ được đẩy ra và dẫn đầu xu hướng.',
        '3_2' => 'Số 3 nói linh hoạt, số 2 thấu cảm: ứng xử tinh tế, dễ khiến người khác tin.',
        '3_3' => 'Khi số 3 lặp lại, khả năng nói và thể hiện được đẩy mạnh, nhưng dễ lan man nếu không tập trung vào một việc chính.',
        '3_4' => 'Số 4 kéo cảm hứng số 3 về thực tế: ý bay bổng dễ thành kết quả cụ thể và bền.',
        '3_5' => 'Số 3 với số 5 làm nhịp sống sôi và hay đổi mới. Cần kiên trì thì mới theo mục tiêu đến cùng.',
        '3_6' => 'Số 3 mang sáng tạo, số 6 mang sự tận tâm: dễ gắn kết mọi người bằng cách vừa vui vừa chu đáo.',
        '3_7' => 'Số 7 làm cách nói của số 3 sâu và sắc hơn: quan điểm vừa dễ truyền vừa có tri thức.',
        '3_8' => 'Số 3 nhạy lời, số 8 quyết đoán. Đàm phán và đưa dự án ra kết quả thường thuận hơn.',
        '3_9' => 'Số 9 nâng tầm cách truyền đạt số 3: sáng tạo dễ hướng sang phục vụ cộng đồng.',
        '3_11' => 'Trực giác số 11 dẫn cách nói của số 3. Thông điệp dễ chạm người khác và đánh thức nhận thức.',
        '3_22' => 'Số 22 mang tầm lớn, số 3 mang linh hoạt: kế hoạch lớn dễ triển khai khi vừa tưởng tượng vừa làm được.',
        '4_1' => 'Số 4 kiên định nâng bước tiên phong số 1: khởi đầu mới thường có chuẩn bị kỹ và thực tế.',
        '4_2' => 'Số 4 mang quy củ cho sự nhạy của số 2: việc chặt mà cách ứng xử vẫn hòa nhã.',
        '4_3' => 'Ý tưởng từ số 3 được số 4 xếp vào việc cụ thể, nên dự án dễ khả thi và bền hơn.',
        '4_4' => 'Khi số 4 lặp lại, tính kỷ luật và khả năng quản trị tăng, tuy nhiên cần chú trọng sự linh hoạt để tránh tự gây áp lực quá lớn.',
        '4_5' => 'Khi số 4 đi cùng số 5, kỷ luật là điểm tựa: muốn đổi mới và tự do vẫn đi đúng quỹ đạo.',
        '4_6' => 'Số 4 và số 6 nghiêng về dựng nền gia đình và sự nghiệp bằng tận tâm và chuẩn mực rõ.',
